import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import "./HomePage.css";

function HomePage() {
  const navigate = useNavigate();
  const [activeMenu, setActiveMenu] = useState("Home");

  const menuItems = [
    { name: "Home", action: () => navigate("/") },
    { name: "Profile", action: () => navigate("/profile") },
    { name: "Bookings", action: () => navigate("/booking") },
    { name: "Payment", action: () => navigate("/payment") },
    { name: "Success", action: () => navigate("/success") },
    { name: "Logout", action: () => { localStorage.removeItem("user"); navigate("/login"); } }
  ];

  const handleMenuClick = (item) => {
    setActiveMenu(item.name);
    item.action();
  };

  return (
    <div className="homepage-container">
      {/* Sidebar */}
      <aside className="sidebar">
        <div className="sidebar-logo">🚗 Parking System</div>
        {menuItems.map((item, index) => (
          <button
            key={index}
            className={`sidebar-btn ${activeMenu === item.name ? "active" : ""}`}
            onClick={() => handleMenuClick(item)}
          >
            {item.name}
          </button>
        ))}
      </aside>

      {/* Main Content */}
      <main className="main-content">
        <div className="welcome-card">
          <h1>{activeMenu}</h1>
          <p>
            {activeMenu === "Home" && "Welcome! Use the sidebar to navigate through the system and book parking slots efficiently."}
            {activeMenu === "Profile" && "View and edit your profile details here."}
            {activeMenu === "Bookings" && "Check your current bookings or create new ones quickly."}
            {activeMenu === "Payment" && "Manage your payment options and view history."}
            {activeMenu === "Success" && "Check the status of your successful bookings."}
            {activeMenu === "Logout" && "You have logged out."}
          </p>
          {activeMenu === "Home" && (
            <button className="start-btn" onClick={() => navigate("/booking")}>
              Start Booking
            </button>
          )}
        </div>
      </main>
    </div>
  );
}

export default HomePage;
